import json
import boto3
import os
import base64
import mimetypes

s3_client = boto3.client('s3')
BUCKET_NAME = os.environ.get('UPLOAD_BUCKET', 'user-uploads-prod')
ALLOWED_PREFIX = 'uploads/'
MAX_SIZE = 10 * 1024 * 1024  # 10MB

def validate_content_type(content_type):
    """Basic content type validation - checks if it looks like a valid MIME type"""
    if not content_type:
        return False
    parts = content_type.split('/')
    return len(parts) == 2 and len(parts[0]) > 0 and len(parts[1]) > 0

def sanitize_filename(filename):
    """Remove path traversal attempts but preserve extension"""
    # Strip directory components
    filename = filename.replace('\\', '/').split('/')[-1]
    # Remove null bytes
    filename = filename.replace('\x00', '')
    if not filename:
        return None
    return filename

def lambda_handler(event, context):
    """Handle file upload requests via API Gateway proxy integration"""
    try:
        if event.get('httpMethod') != 'POST':
            return {'statusCode': 405, 'body': json.dumps({'error': 'Method not allowed'})}

        body = event.get('body', '')
        if event.get('isBase64Encoded', False):
            file_content = base64.b64decode(body)
        else:
            file_content = body.encode('utf-8') if isinstance(body, str) else body

        if len(file_content) > MAX_SIZE:
            return {'statusCode': 413, 'body': json.dumps({'error': 'File too large'})}

        headers = event.get('headers', {}) or {}
        # Case-insensitive header lookup
        content_type = None
        filename = None
        for k, v in headers.items():
            if k.lower() == 'content-type':
                content_type = v
            if k.lower() == 'x-filename':
                filename = v

        if not filename:
            return {'statusCode': 400, 'body': json.dumps({'error': 'X-Filename header required'})}

        filename = sanitize_filename(filename)
        if not filename:
            return {'statusCode': 400, 'body': json.dumps({'error': 'Invalid filename'})}

        if not validate_content_type(content_type):
            return {'statusCode': 400, 'body': json.dumps({'error': 'Invalid content type'})}

        # Upload to S3 - no file extension restriction
        # Content-Type is set from user-provided header
        s3_key = f"{ALLOWED_PREFIX}{filename}"

        s3_client.put_object(
            Bucket=BUCKET_NAME,
            Key=s3_key,
            Body=file_content,
            ContentType=content_type,
            Metadata={
                'uploaded-by': headers.get('x-user-id', 'anonymous'),
                'original-filename': filename
            }
        )

        # Generate a presigned URL for the uploaded file
        presigned_url = s3_client.generate_presigned_url(
            'get_object',
            Params={'Bucket': BUCKET_NAME, 'Key': s3_key},
            ExpiresIn=3600
        )

        return {
            'statusCode': 200,
            'body': json.dumps({
                'message': 'Upload successful',
                'key': s3_key,
                'url': presigned_url
            })
        }
    except Exception as e:
        return {
            'statusCode': 500,
            'body': json.dumps({'error': f'Internal error: {str(e)}'})
        }
